MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  char
    *base64_data;

  size_t
    base64_length;

  /* Validate input parameters */
  if (image_info == (ImageInfo *) NULL)
    return(MagickFalse);
  if (image == (Image *) NULL)
    return(MagickFalse);

  /* Log filename if debugging is enabled */
  if (image->debug != MagickFalse)
    (void) LogMagickEvent(TraceEvent, GetMagickModule(), "%s", image_info->filename);

  /* Clone the image information */
  clone_image = CloneImage(image, 0, 0, MagickTrue, (ExceptionInfo *) NULL);
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  /* Check if the format is "INLINE" */
  magick_info = GetMagickInfo(clone_image->magick, (ExceptionInfo *) NULL);
  if (magick_info == (MagickInfo *) NULL)
  {
    (void) ThrowMagickException(&clone_image->exception, GetMagickModule(),
     CoderError, "UndefinedImageFormat", "`%s' is not a recognized image format",
      clone_image->magick);
    DestroyImage(clone_image);
    return(MagickFalse);
  }

  /* Convert the image to a blob */
  status = WriteImage(image_info, clone_image);
  if (status == MagickFalse)
  {
    DestroyImage(clone_image);
    return(MagickFalse);
  }

  /* Encode the blob data to Base64 */
  base64_length =BlobToBase64(clone_image->blob->length, clone_image->blob->data, &base64_data);
  if (base64_data == (char *) NULL)
  {
    DestroyImage(clone_image);
    return(MagickFalse);
  }

  /* Open a binary blob for writing */
  clone_image->blob = OpenBlob(image_info, clone_image, WriteBinary, &clone_image->exception);
  if (clone_image->blob == (Blob *) NULL)
  {
    (void) RelinquishMemory(base64_data);
    DestroyImage(clone_image);
    return(MagickFalse);
  }

  /* Write the Base64-encoded image data */
  if (WriteBlob(clone_image->blob, base64_length, base64_data) != base64_length)
  {
    (void) RelinquishMemory(base64_data);
    DestroyImage(clone_image);
    return(MagickFalse);
  }

  (void) RelinquishMemory(base64_data);
  DestroyImage(clone_image);
  return(MagickTrue);
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  char
    *base64_data;

  size_t
    base64_length;

  ssize_t
    count;

  void
    *blob;

  clone_image = CloneImage(image, image->columns, image->rows, MagickFalse, NULL);
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  (void) TransformImage(clone_image, image_info->background_color, clone_image->matte);

  magick_info = GetMagickInfo("INLINE", NULL);
  if (magick_info == (MagickInfo *) NULL)
  {
    ThrowBinaryException(OptionError, "UnknownImageFormat", "INLINE");
    return(MagickFalse);
  }

  if (LocaleCompare(clone_image->magick, "INLINE"))
    (void) CloneString(&clone_image->magick, magick_info->name);

  blob = (void *) AcquireBlobMemory(clone_image->scene != 0 ? clone_image->scene : 1);
  if (blob == (void *) NULL)
  {
    (void) RelinquishMagickMemory(clone_image);
    return(MagickFalse);
  }

  status = WriteImage(image_info, clone_image, (Image *) NULL, (Image *) NULL, blob, (size_t *) NULL);

  if (status == MagickFalse)
  {
    (void) RelinquishMagickMemory(blob);
    (void) RelinquishMagickMemory(clone_image);
    return(MagickFalse);
  }

  base64_length = (clone_image->scene != 0 ? clone_image->scene : 1) * 4 * ((clone_image->blob->length + 2) / 3);
  base64_data = (char *) AcquireBlobMemory(base64_length + 1);
  if (base64_data == (char *) NULL)
  {
    (void) RelinquishMagickMemory(blob);
    (void) RelinquishMagickMemory(clone_image);
    return(MagickFalse);
  }

  (void) EncodeBase64((unsigned char *) base64_data, clone_image->blob->data, clone_image->blob->length);
  base64_data[base64_length] = '\0';

  if (image_info->filename != (char *) NULL)
    (void) fprintf(stderr, "Writing INLINE image to %s\n", image_info->filename);

  count = (ssize_t) fwrite(base64_data, 1, base64_length, image_info->file);
  if ((size_t) count != base64_length)
  {
    status = MagickFalse;
  }

  (void) RelinquishMagickMemory(blob);
  (void) RelinquishMagickMemory(base64_data);
  (void) RelinquishMagickMemory(clone_image);

  return(status);
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  register ssize_t
    i;

  size_t
    length;

  StringInfo
    *blob;

  char
    *base64,
    *p;

  if ((image_info == (ImageInfo *) NULL) || (image == (Image *) NULL))
    return (MagickFalse);

  if (GetMagickSetting("filename",image_info) != MagickFalse)
    {
      (void) LogMagickEvent(CoderEvent,GetMagickModule(),
        "filename: %s",image_info->filename);
      (void) SetImageProperty("filename",image_info->filename,image);
    }

  magick_info=GetMagickInfo("INLINE",image_info);
  if (magick_info == (MagickInfo *) NULL)
    return (MagickFalse);

  clone_image=CloneImage(image,0,0,MagickTrue,NULL);
  if (clone_image == (Image *) NULL)
    return (MagickFalse);

  blob=BlobToBase64(clone_image,&length);
  if (blob == (StringInfo *) NULL)
    {
      clone_image=DestroyImage(clone_image);
      return (MagickFalse);
    }

  base64=(char *) StringInfoGetBlob(blob);
  p=(char *) AcquireMemory(length+MagickPathExtent);
  if (p == (char *) NULL)
    {
      (void) CloseBlob(clone_image);
      clone_image=DestroyImage(clone_image);
      blob=DestroyStringInfo(blob);
      return (MagickFalse);
    }

  (void) CopyMagickString(p,base64,length+MagickPathExtent);
  status=WriteBlobBase64(image,p,strlen(p));
  p=(char *) RelinquishMagickMemory(p);
  clone_image=DestroyImage(clone_image);
  blob=DestroyStringInfo(blob);

  return (status ? MagickTrue : MagickFalse);
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image) {
  MagickBooleanType
    status;

  Image
    *clone_image;

  MagickInfo
    *magick_info;

  register ssize_t
    i;

  size_t
    length;

  StringInfo
    *blob;

  assert(image_info != (ImageInfo *) NULL);
  assert(image != (Image *) NULL);
  if (LocaleCompare(image_info->magick,"INLINE") != 0)
    return(False);
  magick_info = GetMagickInfo(image_info->magick, image->exception);
  if (magick_info == (MagickInfo *) NULL)
    return(False);
  clone_image = CloneImage(image, 0, 0, True, image->exception);
  if (clone_image == (Image *) NULL)
    return(False);
  blob = ImageToBlob(clone_image, &length, image->exception);
  if (blob == (StringInfo *) NULL)
    {
      clone_image = DestroyImage(clone_image);
      return(False);
    }
  status = True;
  for (i=0; i < (ssize_t) length; i++)
  {
    MagickLogInfo("Writing INLINE image data", i);
  }
  if (WriteBlobBase64(clone_image, length, StringInfoBytes(blob), StringInfoDatum(blob)) == MagickFalse)
    status = False;
  blob = RelinquishStringInfo(blob);
  clone_image = DestroyImage(clone_image);
  return(status);
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  MagickBooleanType status;
  Image
    *clone_image;

  MagickInfo
    *magick_info;

  StringInfo
    *blob;

  size_t
    length;

  char
    *base64_data;

  assert(image_info != (ImageInfo *) NULL);
  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);

  if (GetMagickBlobSize(image) != 0)
    return(MagickFalse);

  magick_info = GetMagickInfo("INLINE", &image->exception);
  if (magick_info == (MagickInfo *) NULL)
    return(MagickFalse);

  clone_image = CloneImage(image, 0, 0, MagickTrue, &image->exception);
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  blob = (StringInfo *) NULL;
  status = MagickWriteImage(clone_image, image_info, &blob, &image->exception);
  if (status == MagickFalse)
  {
    clone_image = DestroyImage(clone_image);
    return(MagickFalse);
  }

  length = GetBlobSize(blob);
  base64_data = (char *) AcquireMemory(4 * ((length + 3) / 3));
  if (base64_data == (char *) NULL)
  {
    blob = DestroyStringInfo(blob);
    clone_image = DestroyImage(clone_image);
    return(MagickFalse);
  }

  (void) Base64Encode(base64_data, 4 * ((length + 3) / 3), (const unsigned char *) GetData(blob), length);

  (void) WriteBlobString(image, base64_data);

  base64_data = RelinquishMemory(base64_data);
  blob = DestroyStringInfo(blob);
  clone_image = DestroyImage(clone_image);

  return(MagickTrue);
}
